from pathlib import Path
from html import escape
from academy_content import build_academy
from home_content import build_home
from simple_content import simplify_content
from categories import navigation, footer_navigation, build_category_pages
ROOT=Path(__file__).resolve().parents[1]

def button(text,href='contact.html?enquiry=regular-classes#contact-enquiry',style=''): return f'<a class="button {style}" href="{href}">{text}<span aria-hidden="true">↗</span></a>'
def link(text,href):return f'<a class="text-link" href="{escape(href)}">{escape(text)}<span aria-hidden="true">↗</span></a>'
def image(n,alt,extra=''):return f'<img src="assets/{n}.webp" alt="{escape(alt)}" loading="lazy" decoding="async" {extra}>'
def mast(eyebrow,title,lead):return f'<section class="page-hero"><div class="wrap"><span class="eyebrow red">{eyebrow}</span><h1>{title}</h1><p class="lead">{lead}</p></div></section>'
def cta():return ''

def photo(n,caption,alt,category='training'):return f'<figure data-category="{category}"><button class="photo-button" data-photo="assets/{n}.webp" data-caption="{escape(caption)}" aria-label="Enlarge: {escape(caption)}">{image(n,alt)}</button><figcaption>{caption}</figcaption></figure>'
FAQ='''<section class="section wrap faq"><div><span class="eyebrow red">Before you begin</span><h2>A FEW THINGS<br>WORTH KNOWING.</h2></div><div class="faq-list"><details><summary>Do I need any experience?</summary><p>No previous karate experience is needed to explore a beginner program. Tell us your experience level in your trial request so the academy can recommend an appropriate class.</p></details><details><summary>Can my child try a class first?</summary><p>A trial is a useful way to meet the instructor and experience the training environment. A parent or guardian should make the enquiry and confirm age suitability with the academy.</p></details><details><summary>What should I wear or bring?</summary><p>Comfortable sportswear and a water bottle are a sensible starting point. Confirm footwear, equipment and any additional requirements with your instructor before attending.</p></details><details><summary>Where and when are classes held?</summary><p>Free training is conducted at Ganesh Vidyamandir School, Dharavi, and at Pratiksha Nagar, Mumbai. Contact the academy to confirm the current timetable, meeting point and availability before attending.</p></details><details><summary>How much does a trial cost?</summary><p>Karate training conducted by Akash Shinde is completely free of charge. There are no paid classes and no training fees. Please confirm the session time and availability before attending.</p></details></div></section>'''

def write(name,title,body,kind=''):
 from royal_shell import render_shell
 from royal_inner import adapt_page
 body=adapt_page(name,simplify_content(name,body))
 shell=render_shell(name,title,body,kind)
 (ROOT/name).write_text(shell,encoding='utf-8')

home=build_home(button,link)
write('index.html','Free karate training in Mumbai',home,'home-refresh')

academy=build_academy(button,link,image)
write('academy.html','About Royal Sports Academy',academy,'academy-page')

programs=mast('Choose your practice','A STARTING POINT.<br>NOT A LIMIT.','Explore a path that meets you where you are. Beginners, returning students and aspiring competitors can each have a different starting point.')+'<div class="wrap"><p class="page-note">Draft program guide. Karate training is free of charge; there are no paid classes. Exact ages, availability, class duration and schedules require confirmation.</p>'
data=[('kids','Kids karate','Confidence starts small.',7045597,'Instructor guiding a young student',['Movement and coordination','Listening, focus and respectful practice','A positive introduction to karate basics'],'A playful but purposeful introduction to karate. Give growing confidence a place to take root.'),('teens','Teen karate','Find your focus.',7045594,'Students practising their martial arts stances',['Progressive technical foundations','Balance, control and coordination','Personal goals and constructive feedback'],'A practice that makes room for independence, perseverance and steady progress.'),('adults','Adult karate','Make space for yourself.',7045595,'Adult practitioners training basic karate techniques',['Fundamentals at an appropriate pace','Technique, movement and conditioning','A structured approach to continued learning'],'Start something new, return to the mat or deepen your practice. Progress does not require a perfect starting point.'),('sport','Sport karate','Train with intention.',7045473,'Martial artists practising a controlled high kick',['Kata: form, rhythm and precision','Kumite: distance, timing and control','Competition preparation by assessment'],'A proposed pathway for students ready to explore performance. Readiness and eligibility should be discussed with your instructor.')]
for id,title,sub,n,alt,items,desc in data:
 programs+=f'<section class="program-detail" id="{id}"><figure class="detail-photo">{image(n,alt)}</figure><div class="detail-copy"><span class="eyebrow red">{sub}</span><h2>{title}</h2><p>{desc}</p><ul>'+''.join(f'<li>{item}</li>' for item in items)+f'</ul>{button("Ask about classes",f"contact.html?enquiry=regular-classes#contact-enquiry","black")}</div></section>'
programs+='</div>'+FAQ+cta()
write('programs.html','Karate programs',programs)

instructors=mast('About Us / Instructors','TECHNIQUE IS TAUGHT.<br>CHARACTER IS NURTURED.','Clear guidance. Constructive feedback. A training environment where learning matters more than looking perfect.')+'''<section class="wrap section editorial-split"><figure>'''+image(7045600,'An instructor helps a student practise a controlled strike on a pad')+'''</figure><div><span class="eyebrow red">The person behind your progress</span><h2>MORE THAN<br>INSTRUCTIONS.</h2><p>Good coaching notices the details: how you move, what you understand and when you are ready for the next challenge.</p><p>Our coaching vision combines careful demonstration with feedback that students can put into practice.</p><div class="content-note"><strong>Meet Akash Kishor Shinde</strong>A Mumbai-based martial arts practitioner, karate trainer and social worker providing free training to children. <a href="about-akash-shinde.html">Read Akash Shinde’s profile →</a> The training photograph above is illustrative stock imagery, not Akash’s portrait.</div></div></section><section class="wrap section"><div class="section-heading"><h2>KNOW YOUR COACH.<br>ASK THE RIGHT QUESTIONS.</h2><p>Your first conversation is part of finding the right training environment.</p></div><div class="faq-list"><details open><summary>Qualifications and experience</summary><p>Ask about the instructor’s karate background, current qualifications and experience teaching your age group. Verified Royal profiles will make this information easy to find.</p></details><details><summary>How progress is assessed</summary><p>Discuss the training approach, feedback, grading requirements and how readiness for more advanced work is determined.</p></details><details><summary>Care, safety and junior students</summary><p>Ask about supervision, safeguarding, emergency procedures and how activities are adapted to a student’s needs before enrolling.</p></details></div></section>'''+cta()
write('instructors.html','Instructors',instructors)

competition=mast('Sport karate','THE MOMENT IS EARNED.<br>IN THE PRACTICE.','Precision under pressure. Respect in competition. Discover the two complementary disciplines of sport karate.')+'''<section class="wrap section editorial-split"><figure>'''+image(7045473,'Two martial artists working on their movement and kicking technique')+'''</figure><div><span class="eyebrow red">From foundations to performance</span><h2>KATA. KUMITE.<br>ONE COMMITMENT.</h2><div class="coaching-lines"><div><span>KATA</span>Sequences of technique, rhythm and controlled power.</div><div><span>KUMITE</span>Distance, timing and decision-making with a partner.</div></div><p>A competition pathway starts with strong fundamentals. Training intensity, contact and event eligibility should be matched to readiness and discussed with an instructor.</p>'''+link('Explore sport karate training','programs.html#sport')+'''</div></section><section class="competition"><div class="wrap"><div class="competition-top"><div><span class="eyebrow">A record worth standing behind</span><h2>RESULTS.<br>NOT JUST NUMBERS.</h2></div><p>Every result should tell a real story: the athlete, the event, the category and the work that led there.</p></div><figure class="competition-image">'''+image(7045595,'Karate practitioners working together in a training session')+'''<figcaption class="image-tag">Training photography · Not a tournament record</figcaption></figure></div></section><section class="wrap section"><span class="eyebrow red">Royal competition archive</span><div class="results-empty"><h3>THE NEXT STORY<br>BELONGS HERE.</h3><p>No verified tournament results have been provided yet. Royal’s achievement archive will be published with confirmed event names, dates, athlete permissions and results—never invented medal counts.</p></div></section>'''+cta()
write('competition.html','Competition and achievements',competition)

gallery=mast('The photo journal','THE PRACTICE.<br>THE PEOPLE. THE PROGRESS.','A visual study of the attention, encouragement and movement at the heart of martial arts training.')+'''<section class="wrap section"><div class="gallery-controls" role="group" aria-label="Filter photographs"><button class="filter" data-filter="all" aria-pressed="true">All photographs</button><button class="filter" data-filter="training" aria-pressed="false">The practice</button><button class="filter" data-filter="junior" aria-pressed="false">Young learners</button><button class="filter" data-filter="coaching" aria-pressed="false">Coaching</button></div><p id="gallery-count" class="page-note" aria-live="polite">9 photographs</p><div class="gallery-grid">'''
gallery+=photo(7045595,'The basics, revisited.','Two students working on karate guard positions')+photo(7045397,'Self-belief starts here.','Portrait of a young martial arts learner','junior')+photo(7045603,'A little encouragement.','Instructor and student exchange a high five','coaching')+photo(7045593,'Begin with respect.','Karate practitioners bowing before practice')+photo(7045597,'Meet them at their level.','Instructor kneeling to coach a young learner','coaching')+photo(7045395,'Find your balance.','Young learner practising a karate stance','junior')+photo(7045473,'Move with intention.','Two martial artists practising a high kick')+photo(7045594,'Growing, together.','A mixed-age group training together','junior')+photo(7045596,'One detail at a time.','Close-up of a controlled punch at a training pad')
gallery+='</div><p class="gallery-disclaimer">All images are illustrative Pexels stock photography, not Royal Karate Sports students, instructors or premises. Original academy photography is required before public launch.</p></section>'+cta()
write('gallery.html','Photo journal',gallery)

locations=mast('Find your training space','YOUR PRACTICE.<br>CLOSER TO EVERYDAY.','A good training routine begins with a location you can return to. Explore what to look for and tell us your preferred area.')+'''<section class="wrap section location-layout"><figure class="location-photo">'''+image(7045466,'A group of martial arts students in a bright training studio')+'''</figure><div class="location-panel"><span class="eyebrow red">Royal locations</span><h2>THE RIGHT SPACE<br>TO BEGIN.</h2><p>Akash Kishor Shinde provides free karate and martial arts training at Ganesh Vidyamandir School, Dharavi, and at Pratiksha Nagar, Mumbai. Current class times and exact meeting instructions should be confirmed before attending.</p><div class="location-meta"><div><strong>Training centres</strong><span>Ganesh Vidyamandir School, Dharavi<br>Pratiksha Nagar, Mumbai</span></div><div><strong>Class timetable</strong><span>Not yet published</span></div><div><strong>Accessibility</strong><span>To be verified per location</span></div><div><strong>Trial availability</strong><span>Confirmation required</span></div></div>'''+button('Add your preferred area','contact.html?enquiry=regular-classes#contact-enquiry','black')+'''<p class="small">Please do not travel until Royal has confirmed your venue and class. The image is illustrative, not a photograph of a Royal location.</p></div></section>'''+FAQ
write('locations.html','Locations',locations)

info=mast('About this preview','CLEAR INFORMATION.<br>NO FALSE PROMISES.','What’s real, what’s proposed and what still needs to be connected.')+'''<section class="wrap section"><div class="prose"><h2>Website status</h2><p>This is an original website design and working frontend for Royal Karate Sports. It is not a live enrollment service. The supplied brand name and domain are used; ownership and hosting have not been verified. Search indexing is disabled until content is approved.</p><h2>Privacy in this preview</h2><p>No analytics, advertising cookies or remote form services are included. The Contact form keeps entries only in page memory until you leave or refresh. Downloading a draft creates a text file on your device. No enquiry is transmitted and no class is booked. Do not enter sensitive health information or a child’s personal contact details.</p><p>Downloaded files contain the information you typed. Keep or delete them as you choose. A real privacy policy naming the data controller, contact information, purposes, retention periods and applicable rights must be supplied before live collection begins.</p><h2>Content awaiting confirmation</h2><p>Akash Kishor Shinde’s biography, portrait, free-training policy and the Dharavi and Pratiksha Nagar locations were supplied by the website owner. Recognition descriptions follow the owner’s supplied account. Newspaper scans, letters and recognition records are now available in the Media archive; their authenticity and official status have not been independently verified. Phone and email were supplied by the owner for the Contact page. Instagram and Facebook links appear in the site footer. Program age ranges, schedules, exact meeting instructions and safeguarding procedures still require confirmation. No additional awards, ranks or medal counts have been invented.</p><h2>Photography credits</h2><p>Illustrative martial arts photography is sourced from <a href="https://www.pexels.com/search/karate/" target="_blank" rel="noopener noreferrer">Pexels</a>. Akash Kishor Shinde’s profile portrait was supplied by the website owner and is not stock imagery. The academy Our Story group photograph the three Kids Batches training photographs and the five Adult Batches photographs were also supplied by the website owner. Other training photographs depict stock models and studios, not Royal Karate Sports students, staff or facilities. Asset identifiers and source URLs are documented in ASSETS.md. Verify current usage rights and obtain any additional permissions before public use; no model endorsement is implied.</p><h2>Typography</h2><p>Barlow Condensed and Manrope, locally hosted from Google Fonts. Both are distributed under the SIL Open Font License. License files are included with the website package.</p><h2>Design independence</h2><p>Champion’s Karate Club was consulted only for general business-content categories. No competitor photography, contact details, testimonials, affiliations, copy, layouts or visual components are reused.</p></div></section>'''
write('information.html','Privacy, credits and preview status',info)
build_category_pages(write,mast,image,button,link,cta,competition)
# Owner-supplied logo/icons are generated by tools/logo_assets.py.
print('Built',len(list(ROOT.glob('*.html'))),'pages')
